<html lang="{{ str_replace('_', '-', app()->getLocale()) }}">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="description" content="{{ text('welcome.lead') }}">
    <title>{{ config('app.name') }}</title>
    <style>
        :root {
            color-scheme: light dark;
            --ss-color-bg: light-dark(#f8fafc, #020617);
            --ss-color-surface: light-dark(#ffffff, #0f172a);
            --ss-color-surface-muted: light-dark(#f1f5f9, #1e293b);
            --ss-color-border: light-dark(#f3f4f6, #1e293b);
            --ss-color-border-strong: light-dark(#e5e7eb, #334155);
            --ss-color-text: light-dark(#111827, #f9fafb);
            --ss-color-muted: light-dark(#6b7280, #9ca3af);
            --ss-color-accent: light-dark(#1f2937, #f3f4f6);
            --ss-radius-card: 1rem;
            --ss-radius-control: 0.875rem;
            --ss-radius-frame: 1.75rem;
            --ss-frame-padding: 0.75rem;
            --ss-shadow-frame: 0 1px 2px 0 light-dark(rgb(0 0 0 / 0.04), rgb(0 0 0 / 0.3)), 0 24px 48px -28px light-dark(rgb(0 0 0 / 0.18), rgb(0 0 0 / 0.6));
            --ss-font-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
            --ss-font-mono: ui-monospace, "SFMono-Regular", Consolas, monospace;
            --ss-icon-stroke: 1.75;
            --ss-color-tile-border: light-dark(rgb(15 23 42 / 0.09), rgb(255 255 255 / 0.1));
            --ss-space-1: 0.25rem;
            --ss-space-2: 0.5rem;
            --ss-space-3: 0.75rem;
            --ss-space-4: 1rem;
            --ss-space-6: 1.5rem;
            --ss-space-8: 2rem;
            --ss-space-16: 4rem;
        }

        *, *::before, *::after { box-sizing: border-box; }

        body {
            margin: 0;
            background: var(--ss-color-bg);
            color: var(--ss-color-text);
            font-family: var(--ss-font-sans);
            line-height: 1.5;
        }

        svg { display: block; max-width: 100%; height: auto; }

        .ss-muted { color: var(--ss-color-muted); }

        .ss-frame {
            --ss-radius-nested: calc(var(--ss-radius-frame) - var(--ss-frame-padding));
            display: flex;
            flex-direction: column;
            gap: var(--ss-frame-padding);
            padding: var(--ss-frame-padding);
            border: 1px solid var(--ss-color-border);
            border-radius: var(--ss-radius-frame);
            background: var(--ss-color-surface);
            box-shadow: var(--ss-shadow-frame);
        }

        .ss-card {
            padding: var(--ss-space-4);
            border: 1px solid var(--ss-color-border);
            border-radius: var(--ss-radius-card);
            background: var(--ss-color-surface);
        }

        .ss-frame > .ss-card { border-radius: var(--ss-radius-nested); }

        .ss-card--tinted {
            border-color: var(--ss-color-border-strong);
            background: var(--ss-color-surface-muted);
        }

        .ss-icon { display: inline-flex; width: 2.5rem; height: 2.5rem; }
        .ss-icon svg { width: 100%; height: 100%; }
        .ss-icon svg[stroke] { stroke-width: var(--ss-icon-stroke); }

        .ss-icon--tile {
            flex: none;
            padding: var(--ss-space-2);
            border: 1px solid var(--ss-color-tile-border);
            border-radius: var(--ss-radius-control);
            background: var(--ss-color-surface-muted);
        }

        .ss-badge {
            display: inline-flex;
            gap: var(--ss-space-1);
            align-items: center;
            padding: var(--ss-space-1) var(--ss-space-3);
            border: 1px solid var(--ss-color-tile-border);
            border-radius: var(--ss-radius-control);
            background: var(--ss-color-surface);
            color: var(--ss-color-text);
            font-size: 0.75rem;
            font-weight: 500;
        }

        .ss-badge__version { font-family: var(--ss-font-mono); }

        /* Błyskawica przy wersji (ikona zap): co 12 s spokojnie rozjaśnia się do koloru akcentu z lekkim
           powiększeniem i wraca (ok. 1,4 s, bez drgań). */
        .ss-badge__zap {
            flex: none;
            width: 1.5em;
            height: 1.5em;
            margin: -0.25em 0;
            color: var(--ss-color-muted);
            transform-origin: 50% 40%;
            animation: ss-badge-zap 12s ease-in-out infinite;
        }

        .ss-badge__zap[stroke] { stroke-width: var(--ss-icon-stroke); }

        @keyframes ss-badge-zap {
            0%, 12%, 100% { color: var(--ss-color-muted); transform: none; }
            6% { color: var(--ss-color-accent); transform: scale(1.08) rotate(-4deg); }
        }

        @media (prefers-reduced-motion: reduce) {
            .ss-badge__zap { animation: none; }
        }

        .ss-logo-inline { display: inline-block; vertical-align: -0.34em; }
        .ss-logo-inline svg { display: block; width: auto; height: 1.3em; }

        .ss-welcome {
            display: flex;
            min-height: 100vh;
            align-items: center;
            justify-content: center;
            padding: var(--ss-space-4);
        }

        .ss-welcome__card { width: 100%; max-width: 64rem; }

        .ss-welcome__content {
            flex: 1;
            padding: var(--ss-space-8);
            font-size: 0.9375rem;
        }

        .ss-welcome__title { margin: 0 0 var(--ss-space-2); font-size: 1.25rem; font-weight: 600; }
        .ss-welcome__lead { max-width: 40rem; margin: 0; }

        .ss-welcome__heading {
            margin: var(--ss-space-8) 0 var(--ss-space-2);
            font-size: 0.8125rem;
            font-weight: 600;
            letter-spacing: 0.04em;
            text-transform: uppercase;
        }

        .ss-welcome__features {
            display: grid;
            gap: var(--ss-space-4);
            margin: 0;
            padding: 0;
            list-style: none;
        }

        .ss-welcome__feature { display: flex; gap: var(--ss-space-3); align-items: flex-start; }
        .ss-welcome__feature .ss-icon--tile { background: var(--ss-color-surface); }
        .ss-welcome__feature-text { display: flex; flex-direction: column; font-size: 0.875rem; }
        .ss-welcome__feature-title { font-size: 0.9375rem; font-weight: 600; }

        .ss-welcome__footer {
            display: flex;
            flex-wrap: wrap;
            gap: var(--ss-space-4);
            align-items: center;
            justify-content: space-between;
            margin-top: var(--ss-space-8);
        }

        .ss-welcome__built-on { display: inline-flex; gap: var(--ss-space-2); align-items: center; }
        .ss-welcome__laravel { width: 5.5rem; color: var(--ss-color-text); }

        @media (min-width: 40rem) {
            .ss-card { padding: var(--ss-space-6); }
        }

        @media (min-width: 64rem) {
            .ss-welcome__content { padding: clamp(var(--ss-space-6), 7vh, var(--ss-space-16)) clamp(var(--ss-space-8), 3vw, var(--ss-space-16)); }
            .ss-welcome__heading { margin-top: clamp(var(--ss-space-4), 4vh, var(--ss-space-8)); }
            .ss-welcome__features { grid-template-columns: repeat(2, minmax(0, 1fr)); row-gap: clamp(var(--ss-space-3), 2.5vh, var(--ss-space-4)); column-gap: var(--ss-space-6); }
            .ss-welcome__footer { margin-top: clamp(var(--ss-space-4), 4vh, var(--ss-space-8)); }
        }
    </style>
</head>
